import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';

export async function smoke(ctx) {
  const {api, ids, check} = ctx;
  const issue = (await api('GET', '/issues/' + ids.issueId)).issue;
  const actor = ctx.clients.member.user.id === issue.assigneeId ? 'member' : 'owner';
  const assignee = issue.assigneeId === ctx.clients[actor].user.id ? '@me' : issue.assigneeId ?? 'unassigned';
  const source = 'project:' + issue.projectKey + ' AND (status:' + JSON.stringify(issue.statusName) + ' OR status:__absent__) AND assignee:' + assignee +
    ' AND priority>=' + issue.priority + ' AND created>2000-01-01 AND updated<2100-01-01 AND NOT label:__absent__ AND ' + JSON.stringify(issue.title);
  ids.browserQuery = source.replace('assignee:@me', 'assignee:' + issue.assigneeId)
    .replace('(status:' + JSON.stringify(issue.statusName) + ' OR status:__absent__) AND ', '');
  ids.searchQuery = source;
  ids.searchActor = actor;
  await check('compound search grammar precedence dates assignee and highlighted canonical issue', async () => {
    const result = await api('GET', '/search?' + new URLSearchParams({orgId: ids.orgId, q: source}), undefined, actor);
    const match = result.items.find(item => item.id === issue.id);
    assert.ok(match);
    assert.ok(match.highlights.title.some(segment => segment.match && segment.text === issue.title));
    assert.ok(result.total >= 1);
    const invalid = await ctx.request('GET', '/search?' + new URLSearchParams({orgId: ids.orgId, q: 'priority>=9'}));
    assert.equal(invalid.status, 422); assert.equal(invalid.data.error.details.offset, 10);
    const suggestions = await api('GET', '/search/suggestions?' + new URLSearchParams({orgId: ids.orgId, q: 'project:'}));
    assert.ok(suggestions.items.some(item => item.replacement === 'project:' + issue.projectKey));
  });
  await check('saved personal filter is private and saved team filter executes for same-team member', async () => {
    const personal = (await api('POST', '/filters', {orgId: ids.orgId, name: 'Acceptance personal search', query: ids.browserQuery})).filter;
    ids.personalFilterId = personal.id;
    assert.equal(personal.visibility, 'personal');
    assert.equal((await ctx.request('GET', '/filters/' + personal.id, undefined, {actor: 'member'})).status, 404);
    const shared = (await api('POST', '/filters', {orgId: ids.orgId, name: 'Acceptance team search', query: ids.browserQuery, visibility: 'team', teamId: ids.teamId})).filter;
    ids.teamFilterId = shared.id;
    assert.ok((await api('GET', '/filters/' + shared.id + '/search', undefined, 'member')).items.some(item => item.id === issue.id));
    const edited = (await api('PATCH', '/filters/' + personal.id, {description: 'Persisted acceptance query', expectedRevision: 1})).filter;
    assert.equal(edited.revision, 2);
    ids.personalFilterRevision = edited.revision;
    assert.equal((await ctx.request('PATCH', '/filters/' + personal.id, {description: 'Stale', expectedRevision: 1})).status, 409);
  });
  await check('actual search and saved-filter CLI run through owner scoped token', async () => {
    const searched = await ctx.cli(['search', '--org', ids.orgId, '--query', ids.browserQuery]);
    assert.ok(searched.items.some(item => item.id === issue.id));
    const filters = await ctx.cli(['filter', 'list', '--org', ids.orgId]);
    assert.ok(filters.items.some(filter => filter.id === ids.personalFilterId));
    const run = await ctx.cli(['filter', 'run', ids.personalFilterId]);
    assert.ok(run.items.some(item => item.id === issue.id));
  });
}

export async function restart(ctx) {
  await ctx.check('search index and private and team filters survive new server process', async () => {
    const {ids, api} = ctx;
    const searched = await api('GET', '/search?' + new URLSearchParams({orgId: ids.orgId, q: ids.browserQuery}));
    assert.ok(searched.items.some(item => item.id === ids.issueId));
    const personal = (await api('GET', '/filters/' + ids.personalFilterId)).filter;
    assert.equal(personal.query, ids.browserQuery); assert.equal(personal.revision, ids.personalFilterRevision);
    assert.ok((await api('GET', '/filters/' + ids.teamFilterId + '/search', undefined, 'member')).items.some(item => item.id === ids.issueId));
  });
}

export async function remount(ctx) {
  await ctx.check('saved search CLI executes persisted filter after fresh Workspace mount', async () => {
    const result = await ctx.cli(['filter', 'run', ctx.ids.personalFilterId]);
    assert.ok(result.items.some(item => item.id === ctx.ids.issueId));
    assert.equal(result.filter.query, ctx.ids.browserQuery);
  });
}

export async function audit({checks}) {
  const documentation = await readFile('docs/api-insight-search.md', 'utf8');
  for (const required of ['insight:read', 'insight:write', 'team membership', 'offset', 'prefix', 'expectedRevision', 'crew filter', 'highlights']) assert.ok(documentation.includes(required), required);
  checks.push({name: 'Query grammar search-index permissions personal/team filters web and CLI contracts documented; behavior covered by shared/query, server/search+filters, web/search and actual CLI/search suites', ok: true});
}
